import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const MCP_ENTRY = resolve("supabase/functions/mcp/index.ts");
const GENERATED_BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.\n";
const BEGIN_MARKER = "// DYNAMIC_RUNTIME_ATTESTATION_BEGIN";
const END_MARKER = "// DYNAMIC_RUNTIME_ATTESTATION_END";
const RESERVED_IDENTIFIERS = [
  "__dynamicMcpBusinessHandler",
  "__dynamicWithEdgeBuildAttestation",
];
export const RAW_TAIL = `// lovable-mcp-supabase-entry.ts
import { createSupabaseHandler } from "npm:@lovable.dev/mcp-js@0.20.1/stacks/supabase";
Deno.serve(createSupabaseHandler(mcp_default, { functionName: "mcp" }));
`;
export const PATCHED_TAIL = `// lovable-mcp-supabase-entry.ts
import { createSupabaseHandler } from "npm:@lovable.dev/mcp-js@0.20.1/stacks/supabase";
${BEGIN_MARKER}
import {
  withEdgeBuildAttestation as __dynamicWithEdgeBuildAttestation,
} from "../_shared/edgeBuildAttestation.ts";

const __dynamicMcpBusinessHandler = createSupabaseHandler(mcp_default, {
  functionName: "mcp",
});

Deno.serve(async (request) => {
  const response = await __dynamicMcpBusinessHandler(request);
  return request.method === "OPTIONS"
    ? __dynamicWithEdgeBuildAttestation(response, "mcp")
    : response;
});
${END_MARKER}
`;

const checkOnly = process.argv.slice(2).includes("--check");
const unsupportedArgs = process.argv.slice(2).filter((arg) =>
  arg !== "--check"
);
if (unsupportedArgs.length > 0) {
  throw new Error(`Unsupported arguments: ${unsupportedArgs.join(", ")}`);
}

export function postprocessMcpSource(source, { check = false } = {}) {
  if (!source.startsWith(GENERATED_BANNER)) {
    throw new Error("MCP entry is no longer owned by the Lovable MCP generator");
  }

  const markerCount = (marker) => source.split(marker).length - 1;
  const hasExactPatchedTail = source.endsWith(PATCHED_TAIL) &&
    markerCount(BEGIN_MARKER) === 1 && markerCount(END_MARKER) === 1;

  if (check) {
    if (!hasExactPatchedTail) {
      throw new Error(
        "Generated MCP entry is missing the exact attestation wrapper",
      );
    }
    return { output: source, changed: false };
  }
  if (hasExactPatchedTail) return { output: source, changed: false };

  if (markerCount(BEGIN_MARKER) > 0 || markerCount(END_MARKER) > 0) {
    throw new Error(
      "Generated MCP entry contains a partial attestation wrapper",
    );
  }
  if (!source.endsWith(RAW_TAIL)) {
    throw new Error(
      "Generated MCP entry shape changed; refusing an unsafe rewrite",
    );
  }

  const prefix = source.slice(0, -RAW_TAIL.length);
  for (const identifier of RESERVED_IDENTIFIERS) {
    if (prefix.includes(identifier)) {
      throw new Error(`Generated MCP entry collides with ${identifier}`);
    }
  }

  return { output: prefix + PATCHED_TAIL, changed: true };
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const source = readFileSync(MCP_ENTRY, "utf8");
  const result = postprocessMcpSource(source, { check: checkOnly });
  if (result.changed) {
    writeFileSync(MCP_ENTRY, result.output, "utf8");
    console.log("Added deterministic attestation wrapper to generated MCP entry");
  } else if (checkOnly) {
    console.log("Verified generated MCP attestation wrapper");
  } else {
    console.log("Generated MCP attestation wrapper is already current");
  }
}
